sed -i '712i \  const uploadImageToStorage = async (file: File): Promise<string> => {\n    try {\n      const ext = file.name.split(".").pop() || "png";\n      const fileName = `images/${Date.now()}_${Math.random().toString(36).substring(7)}.${ext}`;\n      const storageRef = ref(storage, fileName);\n      await uploadBytes(storageRef, file);\n      return await getDownloadURL(storageRef);\n    } catch (e) {\n      console.warn("Storage upload failed, falling back to base64", e);\n      return await readFileAsBase64WithCompression(file);\n    }\n  };\n' components/ExamEditor.tsx
